SET NAMES utf8mb4;

-- =====================================================================
-- AI LAB HUB — ЄДИНИЙ безпечний SQL усіх ручних партій каталогу (2026-09-20 … 2026-09-21)
-- 69 продуктів (Бізнес та маркетинг, SEO та контент, Дизайн та креатив, Освіта та знання, Переклад та мови,
-- Фінанси та юридичні, Інструменти та автоматизація, Мій дім) + 136 тарифів + прив'язки наявних продуктів.
--
-- БЕЗ ФІКСОВАНИХ id продуктів і тарифів: продукт додається, лише якщо продукту з таким самим
-- нормалізованим URL (без http(s)://, www., кінцевого слеша, регістру) ще немає; його id береться через @pid,
-- категорії/підкатегорії — за slug. Тому id на хостингу й локально можуть бути будь-які, а вже залиті раніше
-- продукти (з fixed-id партій чи додані вручну) не дублюються. created_by = NULL (не залежить від id користувача).
-- Безпечно повторювати; жодних DROP / DELETE / перестворення таблиць. Замінює окремі файли database/batches/*.sql
-- (окрім автозаповнення) — їх одночасно виконувати НЕ треба.
-- =====================================================================

-- ---------------------------------------------------------------------
-- Бізнес та маркетинг (Лідогенерація, CRM)
-- ---------------------------------------------------------------------

-- Apollo.io
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'apollo.io' ORDER BY `id` LIMIT 1);

