INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Apollo.io', NULL, 'https://www.apollo.io', NULL, NULL, 'Платформа для пошуку B2B-клієнтів: база контактів і компаній, розсилки та дзвінки в одному місці, з AI-помічником.', 'Apollo.io містить базу понад 240 млн контактів і 30 млн компаній, з якої можна відібрати потенційних клієнтів за посадою, галуззю чи розміром компанії. Тут же налаштовуються послідовності листів, дзвінки та передача даних у CRM. AI-агенти допомагають досліджувати клієнтів, складати списки, писати персоналізовані листи й нагадувати про повторні звернення.', 'База понад 240 млн контактів і 30 млн компаній\nПослідовності листів з A/B-тестуванням\nДзвінки та запис розмов\nРозширення для Chrome для пошуку контактів на сторінках\nAI-агенти для досліджень і написання листів\nПонад 200 інтеграцій, зокрема з CRM', 'Відділи продажів, стартапи, маркетологи та агенції, що шукають B2B-клієнтів', 'web', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'apollo.io');
