INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Professional', 79.00, 'month', '48 000 кредитів на рік, дзвінки зі США, автоматизація, AI-дослідження (за користувача, річна оплата)' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Organization', 119.00, 'month', '72 000 кредитів на рік, міжнародні дзвінки, SSO, розширений захист; від 3 користувачів (річна оплата)' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Hunter', NULL, 'https://hunter.io', NULL, NULL, 'Сервіс, що знаходить і перевіряє робочі email-адреси та допомагає надсилати холодні листи.', 'Hunter шукає email-адреси співробітників за доменом компанії, перевіряє, що адреса справді працює, і доповнює дані про контакти. Також вміє надсилати послідовності листів і має AI-помічника, який допомагає писати тексти та шукати компанії за описом.', 'Пошук email за доменом компанії або іменем\nПеревірка, що email існує і працює\nПослідовності холодних листів\nAI-помічник для написання листів і пошуку компаній\nЗбагачення даних про контакти', 'Продажники, рекрутери та маркетологи, що шукають контакти для розсилок', 'web', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hunter.io');
