INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Lusha', NULL, 'https://www.lusha.com', NULL, NULL, 'Сервіс, що показує перевірені робочі email і телефони потенційних клієнтів прямо в браузері та CRM.', 'Lusha надає підтверджені контакти — робочі email і прямі номери телефонів людей з бізнес-профілів. Працює як розширення для браузера, має інтеграції з CRM та іншими інструментами й API. Дані відкриваються за кредитами: email коштує 1 кредит, номер телефону — 5, невикористані кредити частково переносяться на наступний місяць.', 'Перевірені робочі email і прямі телефони\nРозширення для браузера\nІнтеграції з CRM та інструментами розсилок\nAPI для автоматизації', 'Відділи продажів і маркетингу, що шукають контакти потенційних клієнтів', 'web', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'lusha.com');
