INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Professional', 69.90, 'month', '600 кредитів на місяць (за рік — $52.45/міс)' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Premium', 399.90, 'month', '3 400 кредитів на місяць (за рік — $299.95/міс)' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'ZoomInfo', NULL, 'https://www.zoominfo.com', NULL, NULL, 'Платформа з даними про компанії та контакти, сигналами інтересу покупців і AI-помічником Copilot для продажів.', 'ZoomInfo об\'єднує дані про компанії й контакти, сигнали того, що клієнт цікавиться покупкою, та автоматизацію робочих процесів відділу продажів. AI-помічник ZoomInfo Copilot шукає компанії з ознаками інтересу, готує персоналізовані повідомлення й автоматизує повторні звернення. Є безкоштовний рівень ZoomInfo Lite з обмеженою кількістю кредитів; платні тарифи розраховуються під замовлення.', 'Дані про компанії та контакти\nСигнали інтересу покупців\nAI-помічник Copilot для пошуку клієнтів і написання повідомлень\nАвтоматизація повторних звернень\nБезкоштовний рівень ZoomInfo Lite', 'Відділи продажів і маркетингу середніх та великих компаній', 'web', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'zoominfo.com');
