INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Платні тарифи', NULL, 'month', 'ціна за запитом (Professional, Advanced, Elite); публічних цін немає' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Zoho CRM', NULL, 'https://www.zoho.com/crm', NULL, NULL, 'Універсальна CRM для ведення клієнтів, угод і воронок продажів з AI-помічником Zia та безкоштовною редакцією на 3 користувачів.', 'Zoho CRM зберігає контакти, угоди й історію спілкування, дозволяє налаштувати кілька воронок продажів, автоматизувати робочі процеси та будувати звіти. У вищих тарифах з\'являються AI-агенти, передбачення результатів угод і рекомендації від помічника Zia. Є безкоштовна редакція для трьох користувачів і мобільні застосунки.', 'Контакти, угоди та воронки продажів\nАвтоматизація робочих процесів\nПошта, дзвінки та календар усередині CRM\nAI-агенти та передбачення (від тарифу Professional)\nМобільні застосунки', 'Малий і середній бізнес, відділи продажів', 'web,mobile', 'course', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'zoho.com/crm');
