INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Enterprise', 50.00, 'month', 'розширені AI-рекомендації Zia, кілька команд, схвалення угод (за рік — $40)' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Ultimate', 65.00, 'month', 'максимальні ліміти, власні AI/ML-моделі (за рік — $52)' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Freshsales', NULL, 'https://www.freshworks.com/crm/sales/', NULL, NULL, 'CRM для відділу продажів від Freshworks: воронка угод, пошта, дзвінки й чат в одному вікні та AI-помічник Freddy.', 'Freshsales показує повну картину по кожному клієнту й автоматично збирає дані про тих, хто написав листом, у чат чи через форму. Пошту, дзвінки й чат можна вести не виходячи з CRM, а воронку угод налаштувати під свій процес. Помічник Freddy AI підказує, які ліди найперспективніші. Є мобільні застосунки та 21 день безкоштовного тестування.', 'Воронка угод у вигляді канбан-дошки\nВбудовані пошта, дзвінки та чат\nОцінка контактів і підказки по угодах\nПослідовності листів і автоматизація\nAI-помічник Freddy AI\nМобільні застосунки', 'Стартапи та малий і середній бізнес з відділом продажів', 'web,mobile', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'freshworks.com/crm/sales');
