INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Pro', 39.00, 'month', 'оцінка контактів, підказки по угодах, послідовності листів, керування територіями (за користувача, річна оплата)' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Enterprise', 59.00, 'month', 'прогнози продажів, доступ на рівні полів, власні модулі, тестове середовище (за користувача, річна оплата)' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Attio', NULL, 'https://attio.com', NULL, NULL, 'Сучасна CRM, що автоматично збирає й доповнює дані про клієнтів і має вбудованого AI-помічника Ask Attio.', 'Attio — платформа для роботи з клієнтами: контакти, компанії та угоди синхронізуються автоматично й доповнюються даними з відкритих джерел. Вбудований AI-помічник Ask Attio відповідає на запитання про клієнтів, а на вищому тарифі працюють AI-агенти, аналіз дзвінків і послідовності листів. Є безкоштовний тариф для трьох користувачів.', 'Автоматична синхронізація контактів і збагачення даних\nAsk Attio — AI-помічник із запитаннями про клієнтів\nAI-агенти та послідовності листів (тариф Pro)\nАналіз дзвінків (тариф Pro)\nРозширені звіти та керування доступом', 'Стартапи та команди продажів, яким потрібна гнучка сучасна CRM', 'web', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'attio.com');
