INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Pipedrive', NULL, 'https://www.pipedrive.com', NULL, NULL, 'CRM для відділу продажів із наочною воронкою угод, автоматизаціями та AI-помічником, що підказує найперспективніші угоди.', 'Pipedrive — CRM, у якій усі клієнти й угоди відображаються на візуальній канбан-воронці: від першого контакту до закриття угоди. Автоматизації самі створюють угоди й завдання, надсилають листи та оновлюють записи, а двосторонній синк пошти дозволяє підключити до п\'яти поштових скриньок. AI-помічник прогнозує ймовірність виграти угоду й підказує, з ким працювати далі. Є мобільні застосунки для iOS та Android і понад 500 інтеграцій з іншими сервісами.', 'Візуальна воронка угод у вигляді канбан-дошки\nАвтоматизації: угоди, завдання, листи й оновлення записів\nДвосторонній синк пошти та шаблони листів\nAI-помічник: прогноз виграшу угод і підказки наступних кроків\nМобільні застосунки для iOS та Android\nПонад 500 інтеграцій (Slack, Zoom, Google Workspace та інші)', 'Відділи продажів, малий і середній бізнес', 'web,mobile', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pipedrive.com');
