INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Surfer SEO', NULL, 'https://surferseo.com', NULL, NULL, 'Платформа для SEO-оптимізації текстів: підказує, що додати в статтю, щоб вона краще ранжувалась у Google та в AI-пошуку.', 'Surfer аналізує понад 500 сигналів ранжування й на цій основі дає поради щодо структури, ключових слів і обсягу тексту — як для нових матеріалів, так і для вже опублікованих сторінок. Відстежує, як бренд згадується в ChatGPT, Gemini, Perplexity та Google AI Overview, має AI-помічника для написання текстів, перевірку на плагіат і автоматичне внутрішнє перелінкування.', 'Поради з оптимізації тексту за 500+ сигналами ранжування\nВідстеження видимості в ChatGPT, Gemini, Perplexity і Google AI Overview\nAI-помічник Surfy для написання текстів\nПеревірка на плагіат і AI-детектор\nАвтоматичне внутрішнє перелінкування', 'SEO-фахівці, контент-маркетологи, редактори й агенції', 'web', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'surferseo.com');
