INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Enterprise', NULL, 'month', 'індивідуальні умови, SSO, white-label, ціна за запитом' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'SE Ranking', NULL, 'https://seranking.com', NULL, NULL, 'SEO-платформа для відстеження позицій сайту, аудиту та видимості бренду у відповідях ChatGPT, Gemini і Perplexity.', 'SE Ranking поєднує звичні SEO-інструменти з відстеженням того, як бренд показується у відповідях AI-платформ. Кожен тариф дає щоденне відстеження позицій за ключовими словами, аудит сайту, кілька проєктів і місць для менеджерів та щомісячні кредити для API. Є 14-денний безкоштовний період без банківської картки.', 'Щоденне відстеження позицій за ключовими словами\nАудит сайту (від 250 000 сторінок на місяць)\nВідстеження видимості в AI-відповідях (ChatGPT, Gemini, Perplexity)\nКілька проєктів і місць для менеджерів\nЩомісячні кредити для API', 'SEO-фахівці, маркетологи та агенції', 'web', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'seranking.com');
