INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'NeuronWriter', NULL, 'https://neuronwriter.com', NULL, NULL, 'Платформа для оптимізації контенту під Google та AI-пошук: генерує SEO-тексти й відстежує відповіді AI-моделей на ваші запитання.', 'NeuronWriter допомагає оптимізувати контент і для позицій у Google, і для видимості в AI-пошуку. Вбудований генеративний AI створює SEO-орієнтовані тексти, а окремий моніторинг показує, що відповідають на ваші запитання Google, ChatGPT, Perplexity та інші моделі. Є помічник Neuro AI, налаштований на SEO, 7-денне тестування і 30-денна гарантія повернення коштів.', 'AI-генерація SEO-текстів\nМоніторинг відповідей AI-моделей (Google, ChatGPT, Perplexity)\nПомічник Neuro AI, налаштований на SEO\nАналізи контенту та окремі проєкти для сайтів', 'Копірайтери, SEO-фахівці та власники сайтів', 'web', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'neuronwriter.com');
