INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Platinum', 93.00, 'month', '25 проєктів, 100 аналізів, 60 000 AI-кредитів (за рік — $77/міс)' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Diamond', 117.00, 'month', '50 проєктів, 150 аналізів, 75 000 AI-кредитів (за рік — $97/міс)' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Yoast SEO', NULL, 'https://yoast.com', NULL, NULL, 'SEO-плагін для WordPress: підказує, як покращити тексти й налаштування сторінок для пошуку; у Premium генерує заголовки й описи за допомогою AI.', 'Yoast SEO працює всередині WordPress і в реальному часі підказує, що виправити в статті чи сторінці, щоб її легше знаходили в пошуку. Платна версія додає менеджер переспрямувань, інструмент внутрішніх посилань, попередній перегляд для соцмереж і необмежену AI-генерацію заголовків та мета-описів. Для інтернет-магазинів є окремий тариф WooCommerce SEO зі структурованими даними товарів.', 'Підказки з SEO для контенту прямо в WordPress\nАналіз контенту в реальному часі (Premium)\nМенеджер переспрямувань і внутрішні посилання (Premium)\nAI-генерація заголовків і мета-описів (Premium)\nSEO для товарів WooCommerce (окремий тариф)', 'Власники сайтів на WordPress, блогери та інтернет-магазини', 'web', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'yoast.com');
