INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Yoast SEO Premium', 118.80, 'year', 'аналіз контенту, менеджер переспрямувань, внутрішні посилання, безлімітний AI для заголовків і описів, Local/News/Video SEO' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Yoast WooCommerce SEO', 178.80, 'year', 'усе з Premium плюс SEO для товарів: структуровані дані, карти сайту WooCommerce, AI-метадані для товарів' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Rank Math', NULL, 'https://rankmath.com', NULL, NULL, 'SEO-плагін для WordPress: перевірка сторінок, генератор schema-розмітки, відстеження позицій і безкоштовна версія.', 'Rank Math — SEO-плагін для WordPress: перевіряє SEO сторінок (понад 30 тестів), генерує schema-розмітку, будує XML-карти сайту й підключається до Google Search Console. У платних тарифах додаються відстеження позицій за ключовими словами та AI Link Genius, а тариф Business дає звіти з власним брендом для агенцій. Є безкоштовна версія з основними можливостями.', 'Понад 30 SEO-перевірок сторінок\nГенератор schema-розмітки\nGoogle Search Console та XML-карти сайту\nВідстеження позицій за ключовими словами (PRO)\nAI Link Genius (PRO)\nЗвіти з власним брендом (Business)', 'Власники сайтів на WordPress, блогери та SEO-агенції', 'web', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'rankmath.com');
