INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Business', NULL, 'year', 'до 100 сайтів клієнтів чи власних, 10 000 ключових слів, звіти з власним брендом (річна підписка)' FROM DUAL WHERE @new = 1;
