INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Google Trends', NULL, 'https://trends.google.com/trends/', NULL, NULL, 'Безкоштовний сервіс Google, що показує, як змінюється інтерес до пошукових запитів у часі та за регіонами.', 'Google Trends аналізує вибірку реальних пошукових запитів у Google й показує, як змінюється інтерес до теми, у яких регіонах вона популярніша та що зараз у тренді. Можна порівнювати до п\'яти тем чи запитів, дивитися історичні дані та добірки на кшталт «Year in Search».', 'Динаміка інтересу до запиту в часі\nПорівняння до п\'яти тем або запитів\nРозподіл інтересу за регіонами\nПошукові запити, що зараз у тренді', 'Маркетологи, SEO-фахівці, журналісти та дослідники', 'web', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'trends.google.com/trends');
