INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Безкоштовно', 0.00, 'free', 'безкоштовний сервіс Google' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Adobe Illustrator', NULL, 'https://www.adobe.com/products/illustrator.html', NULL, NULL, 'Програма для векторної графіки: логотипи, іконки й ілюстрації, що не втрачають якості при будь-якому масштабі, з AI-інструментами Firefly.', 'Adobe Illustrator створює векторну графіку — логотипи, іконки, ілюстрації та брендові матеріали, які можна необмежено збільшувати без втрати якості. AI-функції на основі Firefly перетворюють ескізи чи растрові зображення на редаговану векторну графіку, заповнюють форми варіантами дизайну й створюють вектор чи візерунок за текстовим описом. Програма є для комп\'ютера та iPad, є також веб-версія в бета-режимі, а перші 7 днів можна користуватися безкоштовно.', 'Векторна графіка: логотипи, іконки, ілюстрації\nAI: перетворення ескізу на редаговану графіку (Concept to Vector)\nAI: заповнення форм варіантами дизайну (Generative Shape Fill)\nСтворення вектора й візерунків за текстовим описом\nВерсії для комп\'ютера, iPad і веб (бета)', 'Графічні дизайнери, ілюстратори та бренд-команди', 'web,mobile,desktop', 'course', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'adobe.com/products/illustrator.html');
