INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Illustrator (окремо)', 22.99, 'month', 'річна підписка з оплатою щомісяця; 7 днів безкоштовно' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Affinity', NULL, 'https://www.affinity.studio', NULL, NULL, 'Безкоштовна програма для дизайну від Canva: векторна графіка, редагування фото та верстка сторінок в одному застосунку.', 'Affinity від Canva об\'єднує в одному застосунку векторну графіку для логотипів та ілюстрацій, редагування растрових зображень і верстку сторінок. Підтримує файли PSD, AI та IDML, має неруйнівне редагування й скрипти. Для окремих користувачів безкоштовний; AI-інструменти Canva доступні з платною підпискою Canva. Працює на Mac і Windows, версія для iPad ще в розробці.', 'Векторна студія для логотипів та ілюстрацій\nРедагування фото (піксельна графіка)\nВерстка сторінок\nНеруйнівне редагування та вбудовані скрипти\nСумісність із файлами PSD, AI, IDML', 'Дизайнери, ілюстратори та початківці у графічному дизайні', 'desktop', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'affinity.studio');
