INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Безкоштовно', 0.00, 'free', 'для окремих користувачів; AI-інструменти Canva — з платною підпискою Canva' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Adobe Express', NULL, 'https://www.adobe.com/express/', NULL, NULL, 'Універсальний застосунок для створення дизайну для соцмереж, реклами й документів із шаблонами та AI-функціями Adobe Firefly.', 'Adobe Express — простий редактор із перетягуванням елементів, у якому можна створювати публікації для соцмереж, маркетингові матеріали та документи з понад 100 000 шаблонів. Вбудовані генеративні функції Adobe Firefly створюють і змінюють зображення за текстовим описом. Працює в браузері комп\'ютера та на мобільних телефонах; є безкоштовний план із щоденними безкоштовними генераціями.', 'Понад 100 000 шаблонів для зображень і відео\nГенеративний AI Adobe Firefly: створення й зміна зображень\nЛіцензійні матеріали Adobe Stock (у платних планах)\nЗміна розміру дизайну в один клік (Premium)\nБрендові набори та блокування шаблонів для команд', 'Власники малого бізнесу, маркетологи та автори контенту для соцмереж', 'web,mobile', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'adobe.com/express');
