INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Firefly Pro', NULL, 'month', '7 днів безкоштовно, 4 000 генеративних кредитів на місяць, Photoshop у вебі й на мобільному' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Teams', NULL, 'month', 'брендові набори, блокування шаблонів, 1 ТБ сховища на користувача; лише річна оплата' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Alison', NULL, 'https://alison.com', NULL, NULL, 'Платформа безкоштовних онлайн-курсів із сертифікатами й дипломами про проходження.', 'Alison пропонує понад 6000 безкоштовних онлайн-курсів за дев\'ятьма основними напрямами — від ІТ і бізнесу до здоров\'я та особистого розвитку. Навчання безкоштовне, а сертифікат чи диплом про проходження курсу можна придбати. Є мобільний застосунок із завантаженням курсів для навчання офлайн та підписка Alison Premium, яка прибирає рекламу.', 'Понад 6000 безкоштовних курсів\nСертифікати й дипломи про проходження курсу\nМобільний застосунок із навчанням офлайн\nПідписка Alison Premium без реклами', 'Усі, хто хоче безкоштовно навчатися онлайн і мати підтвердження навичок', 'web,mobile', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'alison.com');
