INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Сертифікат або диплом', NULL, 'one_time', 'платна опція; ціну на головній сторінці не вказано' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Domestika', NULL, 'https://www.domestika.org', NULL, NULL, 'Платформа онлайн-курсів для творчих професій: дизайн, ілюстрація, фотографія, маркетинг та AI.', 'Domestika — спільнота й платформа онлайн-курсів від практикуючих фахівців у дизайні, ілюстрації, фотографії, маркетингу, AI, архітектурі та інших творчих сферах. Навчання у власному темпі, відео можна переглядати знову, є зворотний зв\'язок від спільноти. Учасники Domestika Plus отримують іменний сертифікат, підписаний викладачем, за кожен курс.', 'Курси від професіоналів творчих галузей\nНавчання у власному темпі, відео можна переглядати знову\nСпільнота й зворотний зв\'язок\nІменний сертифікат від викладача за курс (для учасників Plus)', 'Дизайнери, ілюстратори, фотографи, маркетологи та всі, хто навчається творчим професіям', 'web', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'domestika.org');
