INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'TestGorilla', NULL, 'https://www.testgorilla.com', NULL, NULL, 'Платформа для перевірки навичок кандидатів: бібліотека з понад 350 тестів і AI-інструменти для відбору.', 'TestGorilla оцінює кандидатів об\'єктивними тестами ще до співбесіди. У бібліотеці понад 350 тестів: когнітивні, ситуаційні, за конкретною посадою, з програмного забезпечення й програмування, мовні, особистісні та на відповідність культурі компанії. Можна додавати відеопитання й перевіряти код у вбудованому редакторі, а AI оцінює резюме й власні запитання та проводить AI-інтерв\'ю. Є безкоштовний план.', 'Понад 350 тестів: когнітивні, мовні, програмування, особистісні та інші\nВідеопитання\nВбудований редактор коду з автоматичною оцінкою\nAI: оцінка резюме й відповідей, AI-інтерв\'ю\nБаза понад 2 млн кандидатів з перевіреними навичками (Core і Plus)', 'HR-фахівці та рекрутери, що перевіряють навички кандидатів', 'web', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'testgorilla.com');
