INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Plus', 400.00, 'month', 'усе з Core плюс AI-інтерв\'ю, симуляції роботи, необмежені місця; від $4 800 на рік' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Enterprise', NULL, 'month', 'індивідуальні функції та відповідність вимогам, ціна за запитом' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Formative', NULL, 'https://www.formative.com', NULL, NULL, 'Платформа для вчителів: створення завдань і тестів, відповіді учнів у реальному часі та AI-помічник Luna.', 'Formative дозволяє вчителям створювати уроки, оцінювання й практичні завдання та бачити відповіді учнів у реальному часі, щоб одразу коригувати навчання. Понад 20 типів завдань, конструктор з інтеграцією Google Slides, автоматичне оцінювання за рубриками. AI-помічник Luna створює завдання за текстом чи документом, підказки та зворотний зв\'язок.', 'Необмежені уроки, тести й практичні набори\nПонад 20 типів завдань\nВідповіді учнів у реальному часі\nAI-помічник Luna для створення завдань і підказок\nАвтоматичне оцінювання за рубриками\nЗахист від списування', 'Вчителі та школи', 'web', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'formative.com');
