INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Small School', 3125.00, 'year', 'до 250 учнів; $260.42/міс при річній оплаті' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Balanced Assessment', NULL, 'year', 'від 250 учнів, індивідуальна ціна' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Magoosh', NULL, 'https://magoosh.com', NULL, NULL, 'Платформа онлайн-підготовки до іспитів GRE, GMAT, SAT, ACT, TOEFL, IELTS, MCAT і LSAT з відеоуроками й AI-репетитором.', 'Magoosh допомагає готуватися до міжнародних іспитів: GRE, GMAT, SAT, ACT, TOEFL, IELTS, MCAT та LSAT. Курси у власному темпі поєднують відеоуроки й практичні запитання від експертів. Персональний AI-репетитор миттєво оцінює відповіді й крок за кроком пояснює розв\'язання, а прогнозатор балів і аналітика показують прогрес. Є мобільні застосунки для iOS та Android і застосунок із флеш-картками.', 'Підготовка до GRE, GMAT, SAT, ACT, TOEFL, IELTS, MCAT, LSAT\nВідеоуроки та практичні запитання від експертів\nAI-репетитор з миттєвою оцінкою та поясненнями\nПрогнозатор балів і аналітика прогресу\nМобільні застосунки та флеш-картки', 'Абітурієнти й студенти, що готуються до міжнародних іспитів', 'web,mobile', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'magoosh.com');
