INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE c.`slug` = 'education-knowledge' AND s.`slug` = 'tests';
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'ProProfs Quiz Maker', NULL, 'https://www.proprofs.com/quiz-school/', NULL, NULL, 'Конструктор онлайн-тестів і вікторин з AI: тест за темою, автоперевірка та сертифікати за проходження.', 'ProProfs Quiz Maker створює онлайн-тести, вікторини й іспити. AI будує готовий тест за темою чи завантаженим документом, оцінює есе за критеріями й дає пояснення до неправильних відповідей. Є понад 20 типів запитань, налаштування безпеки (прокторинг, вимога веб-камери, перемішування запитань), автоматична видача сертифікатів за успішне проходження та звіти. Працює на комп\'ютерах, планшетах і смартфонах; є безкоштовна версія.', 'AI створює готовий тест за темою або документом\nПонад 20 типів запитань\nАвтоматична перевірка, зокрема AI-оцінка есе\nПрокторинг, блокування вкладок, вимога веб-камери\nАвтоматична видача сертифікатів за проходження\nЗвіти та аналітика результатів', 'Тренери, викладачі та організації, що перевіряють знання', 'web', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'proprofs.com/quiz-school');
