INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Kahoot!', NULL, 'https://kahoot.com', NULL, NULL, 'Ігрова платформа для навчання: створення вікторин і тестів, проведення в класі чи онлайн і AI-генератор запитань.', 'Kahoot! дозволяє створювати вікторини й інтерактивні матеріали, проводити їх і грати разом або поодинці. Є AI-генератор вікторин, картки для запам\'ятовування, навчальні групи та підготовка до іспитів. Працює в браузері й має застосунки для iOS та Android. Почати можна безкоштовно, без банківської картки.', 'Створення вікторин та інтерактивних матеріалів\nAI-генератор вікторин\nКартки для запам\'ятовування й навчальні групи\nПідготовка до іспитів\nЗастосунки для iOS та Android', 'Вчителі, учні, тренери та команди', 'web,mobile', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'kahoot.com');
