INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Kahoot! 360', NULL, 'month', 'план для організацій; актуальну ціну див. на офіційній сторінці' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Reverso', NULL, 'https://www.reverso.net', NULL, NULL, 'Безкоштовний перекладач із прикладами вживання слів у контексті, словником і застосунками для телефона, браузера та комп\'ютера.', 'Reverso показує переклад слів, виразів та ідіом разом із реальними прикладами вживання — від розмовної мови до ділової й технічної. Є словник, синоніми, відмінювання дієслів, вимова та навчальні функції: власні списки слів, тести й картки. Перекладає між 29 мовами, зокрема українською. Основні функції безкоштовні; є застосунки для iOS та Android, розширення для Chrome і Edge та програма для Windows і macOS. Платна підписка Premium дає розширені навчальні можливості.', 'Переклад слів, виразів та ідіом із прикладами вживання\nСловник, синоніми та відмінювання дієслів\nВласні списки слів, тести й картки для навчання\nЗастосунки для iOS, Android, Windows і macOS\nРозширення для Chrome і Edge', 'Студенти, вчителі, перекладачі та всі, хто вивчає мови', 'web,mobile,desktop', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'reverso.net');
