INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Premium', NULL, 'year', 'розширені навчальні можливості; ціну не підтверджено' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Weglot', NULL, 'https://www.weglot.com', NULL, NULL, 'Сервіс для перекладу сайтів: робить сайт багатомовним за лічені хвилини без програмування, з підтримкою SEO для кожної мови.', 'Weglot автоматично перекладає сайт за допомогою AI і дозволяє правити переклади вручну чи замовити їх у професійних перекладачів. Підтримує правила глосарію, пам\'ять перекладів, переклад зображень, переспрямування відвідувачів на їхню мову та SEO для кожної мови (теги hreflang, перекладені адреси сторінок). Працює з WordPress, Shopify, Wix, BigCommerce, Webflow, Squarespace, Drupal і з будь-яким сайтом через код. Є безкоштовний план і 14-денний пробний період для платних.', 'AI-переклад сайту з правилами глосарію\nSEO для кожної мови: теги hreflang та перекладені адреси\nАвтоматичне переспрямування відвідувачів на їхню мову\nПрофесійні перекладачі та пам\'ять перекладів\nІнтеграції: WordPress, Shopify, Wix, Webflow та інші\nКомандна робота, експорт та імпорт перекладів', 'Власники сайтів, інтернет-магазини та маркетологи', 'web', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'weglot.com');
