INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Enterprise', NULL, 'month', 'індивідуальні умови, ціна за запитом' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Wordly', NULL, 'https://www.wordly.ai', NULL, NULL, 'AI-сервіс живого перекладу для зустрічей і подій: переклад мовлення в реальному часі, субтитри, стенограми та підсумки.', 'Wordly перекладає мовлення на зустрічах і подіях у реальному часі: учасники чують переклад та бачать субтитри своєю мовою. Працює з Zoom, Teams, Google Meet і WebEx та підтримує очні, онлайн- та гібридні формати й вебінари. Підтримує понад 3000 мовних пар, створює стенограми з перекладом і AI-підсумки з головними висновками, дозволяє налаштувати глосарії та списки заборонених слів. Тариф залежить від кількості годин на рік.', 'Переклад мовлення в реальному часі та живі субтитри\nІнтеграція з Zoom, Teams, Google Meet і WebEx\nПонад 3000 мовних пар\nСтенограми з перекладом і AI-підсумки\nНалаштовувані глосарії та списки заборонених слів', 'Організатори конференцій, вебінарів і міжнародних зустрічей компаній', 'web', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'wordly.ai');
