INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Immersive Translate', NULL, 'https://immersivetranslate.com', NULL, NULL, 'Розширення для браузера, що перекладає веб-сторінки двомовно — оригінал і переклад поруч, а також PDF, відео й документи.', 'Immersive Translate — розширення для браузера, яке показує переклад веб-сторінки поруч з оригіналом. Крім сторінок, перекладає PDF із збереженням розкладки, субтитри відео, електронні книги ePUB, Google Docs, зображення та комікси, а також текст у полях вводу й на виділення чи наведення. Може працювати з AI-моделями DeepSeek, DeepL, OpenAI, Claude і Gemini. Доступне для Chrome, Edge, Safari та Firefox; вміст користувача не зберігається.', 'Двомовний переклад веб-сторінок\nПереклад PDF із збереженням розкладки\nПереклад відео та субтитрів\nПереклад ePUB, Google Docs, зображень і коміксів\nПідключення AI-моделей: DeepSeek, DeepL, OpenAI, Claude, Gemini', 'Читачі іноземних сайтів і документів, студенти та дослідники', 'web', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'immersivetranslate.com');
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE c.`slug` = 'translation-languages';
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE c.`slug` = 'translation-languages' AND s.`slug` = 'translation';
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Wave', NULL, 'https://www.waveapps.com', NULL, NULL, 'Безкоштовне бухгалтерське програмне забезпечення для малого бізнесу: рахунки, облік доходів і витрат, чеки.', 'Wave допомагає підприємцям вести облік доходів і витрат, виставляти рахунки й кошториси, приймати оплату онлайн та впорядковувати чеки перед сплатою податків. Тариф Starter безкоштовний: необмежені кошториси, рахунки, рахунки на оплату й облікові записи та мобільний застосунок. Платний Pro додає автоімпорт банківських транзакцій, автоматичну категоризацію, необмежений облік чеків, нагадування про прострочені платежі та власний бренд. Окремо є послуга Wave Advisors із виділеним бухгалтером.', 'Облік доходів і витрат\nРахунки, кошториси та онлайн-оплата\nЗахоплення й організація чеків\nАвтоімпорт і категоризація банківських транзакцій (Pro)\nМобільний застосунок', 'Малий бізнес, фрилансери та підприємці', 'web,mobile', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'waveapps.com');
