INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Wave Advisors', 149.00, 'month', 'від $149 на місяць: виділений бухгалтер і щомісячна фінансова звітність' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Rocket Lawyer', NULL, 'https://www.rocketlawyer.com', NULL, NULL, 'Онлайн-сервіс правових документів: створення й підпис документів, перевірка договорів AI-помічником і консультації юристів.', 'Rocket Lawyer — платформа, де можна створювати персоналізовані юридичні документи, підписувати їх електронно, перевіряти договори та отримувати консультації юристів. AI-помічник Rocket Copilot без обмежень відповідає на запитання й показує в договорах ключові умови та ризики. Є генератор назв і логотипів для бізнесу та послуга реєстрації бізнесу. Кожен план має 7 днів безкоштовного періоду.', 'Створення юридичних документів і електронний підпис\nAI-помічник Rocket Copilot: питання та перевірка договорів\nКонсультації юристів (письмові питання та живі консультації)\nНагадування про юридичні дії\nГенератор назв і логотипів, реєстрація бізнесу', 'Власники малого бізнесу та люди, яким потрібні юридичні документи', 'web', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'rocketlawyer.com');
