INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Plus', 20.75, 'month', '36 письмових питань і 12 живих консультацій; $249 на рік (річна оплата)' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Pro', 29.08, 'month', 'необмежені питання й консультації; $349 на рік (річна оплата)' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'DoNotPay', NULL, 'https://donotpay.com', NULL, NULL, 'AI-помічник для захисту прав споживачів: скасування підписок, оскарження штрафів та інші побутові юридичні й бюрократичні процедури.', 'DoNotPay допомагає автоматизувати побутові юридичні й бюрократичні справи: скасовує небажані підписки й пробні періоди, оскаржує штрафи за паркування та спірні платежі, шукає невитребувані гроші, допомагає з рахунками. Є віртуальні картки й тимчасові номери для приватності, захист від автодзвінків і повідомлення про шахрайські списання. Сервіс сам зазначає, що не є юридичною фірмою й не надає юридичних порад — це платформа юридичної інформації та самодопомоги.', 'Скасування підписок і пробних періодів\nОскарження штрафів, спірних платежів і повернення коштів\nПошук невитребуваних грошей\nВіртуальні картки й тимчасові номери\nЗахист від автодзвінків і шахрайства', 'Споживачі, які хочуть швидко розв\'язувати побутові спори й бюрократичні питання', 'web', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'donotpay.com');
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE c.`slug` = 'finance-legal';
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE c.`slug` = 'finance-legal' AND s.`slug` = 'legal-services';
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Legora', NULL, 'https://www.legora.com', NULL, NULL, 'AI-платформа для юристів: юридичні дослідження, перегляд документів і підготовка текстів із надбудовами для Word та Outlook.', 'Legora — спільна AI-платформа для юридичної роботи. Допомагає з юридичними дослідженнями в різних юрисдикціях, табличним переглядом великої кількості документів та складанням і редагуванням текстів через надбудову для Word і редактор. Є Agent, який виконує складні завдання від початку до кінця, моніторинг змін у регулюванні та портал для спільної роботи з клієнтами. Використовується в M&A, судових спорах, банківській справі, податках і страхуванні. Компанія заявляє про сертифікації ISO 27001, ISO 42001, SOC 2 Type II та відповідність GDPR і HIPAA, а також про те, що не навчає AI на даних клієнтів.', 'AI-дослідження в різних юрисдикціях\nТабличний перегляд документів (Tabular Review)\nНадбудови для Word та Outlook і редактор\nAgent для виконання складних завдань від початку до кінця\nМоніторинг змін у регулюванні', 'Юридичні фірми, юридичні відділи компаній та державний сектор', 'web,mobile', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'legora.com');
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE c.`slug` = 'finance-legal';
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE c.`slug` = 'finance-legal' AND s.`slug` = 'legal-services';
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Microsoft Power Automate', NULL, 'https://www.microsoft.com/en-us/power-platform/products/power-automate', NULL, NULL, 'Платформа Microsoft для автоматизації робочих процесів з мінімумом коду: хмарні потоки, автоматизація дій на комп\'ютері й аналіз процесів.', 'Power Automate дозволяє налаштовувати автоматизацію за допомогою хмарних потоків, потоків для комп\'ютера (у режимі з участю користувача чи без нього) та аналізу процесів. Платні плани відкривають стандартні й преміальні конектори, сховище Dataverse та керовані середовища. Premium призначено для окремого користувача, а Process і Hosted Process — для запуску автоматизації без участі людини. Є 30-денний безкоштовний пробний період.', 'Хмарні потоки для автоматизації між сервісами\nАвтоматизація на комп\'ютері: з участю користувача (Premium) і без неї (Process)\nАналіз процесів і завдань\nСтандартні й преміальні конектори\nКеровані середовища', 'Компанії та відділи, що автоматизують повторювані робочі процеси', 'web', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'microsoft.com/en-us/power-platform/products/power-automate');
