INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Process', 150.00, 'month', 'за бота; річна оплата; автоматизація без участі користувача' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Hosted Process', 215.00, 'month', 'за бота; річна оплата; розміщений процес' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'UiPath', NULL, 'https://www.uipath.com', NULL, NULL, 'Платформа автоматизації бізнес-процесів: роботизована автоматизація (RPA), AI-агенти та оркестрація.', 'UiPath поєднує роботизовану автоматизацію процесів (RPA), AI-агентів і оркестрацію, щоб автоматизувати бізнес-процеси в організаціях різного розміру. Є інтелектуальна обробка документів, керування бізнес-процесами, автоматизація тестування та контроль над AI. Розгортання можливе в хмарі чи на власних серверах. Тариф Community безкоштовний назавжди, Basic — від $25 на місяць, Standard і Enterprise розраховуються під замовлення.', 'Роботизована автоматизація процесів (RPA) та API-процеси\nAI-агенти та оркестрація бізнес-процесів\nІнтелектуальна обробка документів\nАвтоматизація тестування\nКонтроль над AI та керування доступом\nРозгортання в хмарі чи на власних серверах', 'Підприємства й команди, що автоматизують бізнес-процеси', 'web', 'course', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'uipath.com');
