INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Activepieces', NULL, 'https://www.activepieces.com', NULL, NULL, 'Відкрита платформа автоматизації без коду: робочі процеси, AI-агенти та понад 760 інтеграцій, яку можна розгорнути у себе.', 'Activepieces дозволяє будувати робочі процеси, AI-агентів і таблиці без коду та підключати понад 760 інтеграцій. Є функція «Chat to automation» — створення автоматизації через чат, а також API та SDK. Код відкритий (TypeScript), тож можна писати власні інтеграції; безкоштовну Community-версію можна розгорнути на власних серверах, а хмарна версія має регіон у Франкфурті. Усі тарифи мають необмежену кількість потоків.', 'Конструктор робочих процесів без коду\nAI-агенти та таблиці\nПонад 760 інтеграцій\nСтворення автоматизації через чат\nВідкритий код і розгортання на власних серверах', 'Команди й розробники, що автоматизують процеси, зокрема з власним розміщенням', 'web', 'basic', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'activepieces.com');
