INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Team', 200.00, 'month', '50 000 кредитів на місяць, до 25 користувачів' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Ultimate', NULL, 'month', 'необмежені користувачі, річні кредити; ціна за запитом' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Lindy', NULL, 'https://www.lindy.ai', NULL, NULL, 'AI-асистент, що виконує робочі завдання: чернетки, підсумки, оновлення інструментів і зустрічі — прямо в Slack та iMessage.', 'Lindy працює як AI-колега: у Slack чи через iMessage бере на себе повсякденні завдання — пише чернетки, робить підсумки, оновлює інструменти, записує зустрічі та веде розклад. Має понад 40 навичок і можливість створювати власні, виконує завдання за розкладом, дозволяє обирати модель AI, вимагати погодження дій людиною та працювати з комп\'ютером. Підтримує тисячі інтеграцій і MCP. Для тих, хто підключається через Slack, є 7-денний пробний період.', 'AI-асистент у Slack та iMessage\nПонад 40 навичок і власні навички\nРегулярні завдання за розкладом\nЗапис зустрічей, нотатки й розклад\nВибір моделі AI та погодження дій людиною\nТисячі інтеграцій і MCP', 'Команди й фахівці, що делегують рутинні завдання AI-асистентові', NULL, 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'lindy.ai');
