INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Enterprise', NULL, 'month', 'усе з Max плюс вимоги до відповідності; ціна за запитом' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'PlantSnap', NULL, 'https://www.plantsnap.com', NULL, NULL, 'Мобільний застосунок, що за фото визначає рослини, дерева й гриби та підказує, як за ними доглядати.', 'PlantSnap за допомогою AI визначає рослини, дерева й гриби за фотографією і дає довідкову інформацію про них. Є персоналізовані поради з догляду — графік поливу, освітлення, — AI-помічник, який діагностує хвороби (наприклад, чорну плямистість троянд), енциклопедія рослин і спільнота, де користувачі діляться досвідом. Доступний для iOS та Android; є платна підписка PlantSnap Premium.', 'Визначення рослин, дерев і грибів за фото\nПерсоналізовані поради з догляду: полив, освітлення\nAI-помічник для діагностики хвороб рослин\nЕнциклопедія рослин\nСпільнота любителів рослин', 'Любителі рослин, садівники й початківці', 'mobile', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'plantsnap.com');
