INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE c.`slug` = 'my-home' AND s.`slug` = 'garden';
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Blossom', NULL, 'https://blossomplant.com', NULL, NULL, 'Мобільний застосунок для догляду за рослинами: визначення понад 30 000 видів, діагностика хвороб і нагадування про полив.', 'Blossom допомагає визначати понад 30 000 рослин, квітів, сукулентів і дерев за фото, діагностувати хвороби рослин та дізнаватися, як їх запобігати й лікувати. Персональні нагадування про полив і підживлення, поради з догляду та колекція «Мій сад» для власних рослин. Є журнал з фото для відстеження росту, розширений пошук за складністю догляду, освітленням і безпекою для тварин, а також графік вирощування їстівних рослин. Доступний на iOS та Android; вимірювач світла є лише на Android.', 'Визначення понад 30 000 рослин за фото\nДіагностика хвороб рослин і поради з лікування\nНагадування про полив і підживлення\nКолекція власних рослин і журнал росту з фото\nПошук за складністю догляду, освітленням і безпекою для тварин', 'Власники домашніх рослин і початківці-садівники', 'mobile', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'blossomplant.com');
