INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Greg', NULL, 'https://greg.app', NULL, NULL, 'Застосунок для догляду за домашніми рослинами: розпізнає рослину за фото та складає персональний графік поливу.', 'Greg визначає рослину за фото за допомогою технології PlantVision і складає персональний план поливу з нагадуваннями з урахуванням виду рослини, розміру горщика та умов у домі. Вимірює освітленість і підказує, де краще поставити рослину, має спільноту, де можна вирішувати проблеми з іншими любителями, та стрічку для спілкування й відстеження прогресу. Завантаження безкоштовне, додаткові функції — за підпискою Super Greg.', 'Визначення рослини за фото (PlantVision)\nПерсональний графік поливу з нагадуваннями\nВимірювання освітленості та поради щодо розміщення\nСпільнота для розв\'язання проблем з рослинами\nВідстеження прогресу рослин', 'Власники домашніх рослин, зокрема початківці', 'mobile', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'greg.app');
