INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Super Greg', 29.99, 'year', 'стандартна річна підписка; завантаження безкоштовне, додаткові функції за підпискою' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Plant Parent', NULL, 'https://apps.apple.com/us/app/plant-parent-plant-care-guide/id1612792132', NULL, NULL, 'Застосунок для догляду за кімнатними й садовими рослинами: нагадування, вимірювач світла, визначення та діагностика.', 'Plant Parent допомагає доглядати за рослинами всередині й надворі: розумні нагадування про полив, підживлення, обрізання, розмноження й пересадку, вимірювач освітленості, визначення рослини за фото та персональні плани догляду. Робить діагностику хвороб за фото хворої рослини й пропонує лікування. Завантаження безкоштовне; платні підписки Premium, Family Premium і Lifetime відкривають додаткові можливості.', 'Нагадування про полив, підживлення, обрізання й пересадку\nВимірювач освітленості\nВизначення рослини за фото\nПерсональні плани догляду\nДіагностика хвороб за фото', 'Власники кімнатних і садових рослин', 'mobile', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'apps.apple.com/us/app/plant-parent-plant-care-guide/id1612792132');
