INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Plantum', NULL, 'https://myplantum.com', NULL, NULL, 'Застосунок для визначення рослин за фото з діагностикою хвороб, порадами з догляду та консультаціями експертів.', 'Plantum визначає рослини за фото за допомогою AI (база понад 40 тисяч рослин), діагностує проблеми зі здоров\'ям рослин і дає персональні поради щодо поливу, освітлення та іншого догляду. Є можливість отримати пораду від ботаніків-експертів. Застосунок доступний для iOS та Android; для студентів і викладачів ботаніки, медицини чи біології діє окрема освітня програма.', 'Визначення рослин за фото (понад 40 тисяч рослин)\nДіагностика хвороб рослин\nПерсональні поради з догляду\nКонсультації експертів-ботаніків\nОсвітня програма для студентів і викладачів', 'Любителі рослин, садівники, студенти', 'mobile', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'myplantum.com');
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE c.`slug` = 'my-home';
