INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Garden Answers', NULL, 'https://www.gardenanswers.com', NULL, NULL, 'Застосунок для визначення рослин за фото з розпізнаванням хвороб і шкідників та порадами садових експертів.', 'Garden Answers визначає будь-яку рослину — достатньо навести на неї камеру телефона чи планшета. Показує, чи є на рослині хвороби або шкідники, і дає доступ до садових експертів, яким можна поставити запитання. Історія попередніх питань і відповідей зберігається. Є застосунки для iOS та Android і сайт.', 'Визначення рослин за фото\nРозпізнавання хвороб і шкідників\nПоради садових експертів\nІсторія питань і відповідей', 'Садівники й любителі рослин', 'web,mobile', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gardenanswers.com');
