INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE c.`slug` = 'my-home' AND s.`slug` = 'garden';
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Pl@ntNet', NULL, 'https://plantnet.org', NULL, NULL, 'Безкоштовна платформа для визначення рослин за фото, що поєднує AI з науковою спільнотою.', 'Pl@ntNet — науковий проєкт, у якому користувачі фотографують рослини, а система підказує вид за допомогою розпізнавання зображень; спільнота потім перевіряє й уточнює визначення. База охоплює понад 84 тисячі видів і понад 1,4 мільярда зображень у 77 флористичних проєктах. Користуватися можна безкоштовно через застосунки для iOS та Android або веб-версію. Проєкт ведуть французькі наукові установи CIRAD, INRAE, INRIA та IRD.', 'Визначення рослин за фото\nПеревірка визначень спільнотою\nБаза понад 84 тисяч видів\nБезкоштовні застосунки й веб-версія', 'Садівники, ботаніки-аматори, студенти та всі, хто цікавиться рослинами', 'web,mobile', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'plantnet.org');
