INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'GardenTags', NULL, 'https://www.gardentags.com', NULL, NULL, 'Садовий застосунок-спільнота: безкоштовне визначення рослин, ведення саду та понад 400 000 фото від користувачів.', 'GardenTags поєднує визначення рослин за фото, ведення власного саду з нагадуваннями про завдання та спільноту садівників. Користувачі наповнюють енциклопедію рослин, а понад 400 000 їхніх фото слугують натхненням для посадок. Визначення рослин і керування садом безкоштовні; є також платна опція Premium. Застосунки для iOS та Android.', 'Безкоштовне визначення рослин за фото\nКерування садом і завдання з догляду\nЕнциклопедія рослин від спільноти\nПонад 400 000 фото користувачів для натхнення', 'Садівники та любителі рослин', 'mobile', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gardentags.com');
