INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Free', 0.00, 'free', 'безкоштовне визначення рослин, керування садом та інше' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Growli', NULL, 'https://www.getgrowli.app', NULL, NULL, 'AI-помічник для садівника: щоденні поради з урахуванням погоди, визначення рослин, попередження про заморозки та календар посадок.', 'Growli вивчає ваш клімат і місце розташування, стежить за погодою та щодня підказує, що потрібно саду, з поясненнями. Є ранкові зведення із завданнями, визначення рослин за фото, попередження про заморозки й негоду з порадами щодо захисту, розмовний AI, який пам\'ятає історію вашого саду, та сезонний календар посадок із термінами сівби й прогнозом врожаю. Основні функції працюють офлайн. Найточніші локальні кліматичні дані наразі для Великої Британії та США. Доступний для iOS та Android.', 'Щоденні поради з урахуванням погоди й місця\nВизначення рослин за фото\nПопередження про заморозки та негоду\nРозмовний AI, що пам\'ятає історію саду\nКалендар посадок із термінами сівби й прогнозом врожаю', 'Садівники та городники', 'mobile', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'getgrowli.app');
