INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Planter', NULL, 'https://planter.garden', NULL, NULL, 'Планувальник городу: розташуйте грядки перетягуванням, дізнайтеся, які рослини поруч ростуть добре, і слідкуйте за календарем посадок.', 'Planter допомагає спланувати город: рослини перетягуються на схему ділянки, застосунок показує, які рослини добре сусідять, а яких треба уникати, і підказує терміни посіву, розсади й збору врожаю. У бібліотеці понад 80 рослин і понад 1000 сортів, є можливість додавати власні. Працює у вебі, на iOS, Android та Amazon Fire. Безкоштовний план дозволяє вести один город; Premium додає необмежену кількість, прибирає рекламу й відкриває веб-версію.', 'Схема городу з перетягуванням рослин\nСумісність рослин на грядці\nКалендар посіву, розсади й збору врожаю\nПонад 80 рослин і 1000 сортів, власні рослини\nВеб, iOS, Android та Amazon Fire', 'Городники й садівники-початківці', 'web,mobile', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'planter.garden');
