INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Premium', 24.99, 'year', 'необмежені городи, без реклами, веб-застосунок, власні фони' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Lifetime', 99.99, 'one_time', 'функції Premium без підписки' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Almanac Garden Planner', NULL, 'https://gardenplanner.almanac.com', NULL, NULL, 'Онлайн-планувальник городу від Old Farmer\'s Almanac: схема грядок, календар посадок за вашою місцевістю та нагадування.', 'Almanac Garden Planner дозволяє накреслити грядки, додати рослини й переміщувати їх, щоб знайти найкращу схему; підтримує підняті грядки й метод квадратного фута. Календар посадок і збору врожаю підлаштовується під вашу місцевість за базою з понад 5000 метеостанцій. У базі понад 250 овочів, трав, фруктів і квітів та тисячі сортів насіння від великих постачальників. Є попередження щодо сівозміни, нагадування електронною поштою та щоденник саду. Доступний 7-денний безкоштовний період.', 'Схема грядок з підтримкою піднятих грядок і квадратного фута\nКалендар посадок за місцевістю (5000+ метеостанцій)\nБаза понад 250 рослин і тисячі сортів насіння\nПопередження щодо сівозміни та нагадування\nЩоденник саду', 'Городники та любителі вирощувати овочі', 'web', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gardenplanner.almanac.com');
