INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Gardener\'s Supply Garden Planner', NULL, 'https://www.gardeners.com/garden-planner', NULL, NULL, 'Безкоштовний онлайн-планувальник овочевого городу за методом квадратного фута з готовими схемами.', 'Планувальник від Gardener\'s Supply — безкоштовний вебінструмент для проєктування овочевого городу за методом квадратного фута. У ньому 26 готових схем городу, зокрема з піднятими грядками; можна перетягувати культури на сітку, і планувальник сам розраховує кількість рослин. Є довідник овочів, калькулятор ґрунту та інструкції з вирощування й догляду.', '26 готових схем городу\nПеретягування культур на сітку з автоматичним розрахунком кількості рослин\nДовідник овочів\nКалькулятор ґрунту\nІнструкції з вирощування й догляду', 'Городники, зокрема початківці', 'web', 'none', 'published', 'found', '2026-09-20 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'gardeners.com/garden-planner');
