INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Безкоштовно', 0.00, 'free', 'безкоштовний вебінструмент' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Petcube', NULL, 'https://petcube.com', NULL, NULL, 'Розумні камери й застосунок для спостереження за котами та собаками: відео наживо, AI-сповіщення й двосторонній зв\'язок.', 'Petcube випускає розумні пристрої для догляду за котами та собаками й застосунок до них. Через камери можна бачити улюбленця й говорити з ним, підкидати ласощі, гратися віддалено та запобігати тривожній поведінці. Застосунок дає відео наживо, AI-сповіщення та двосторонній зв\'язок. Підписка Petcube Care додає історію відео та розумні сповіщення, є також послуга Petcube Online Vet — чат із ліцензованим ветеринаром. Застосунок працює на iOS та Android.', 'Розумні камери для спостереження за котами й собаками\nВідео наживо та двосторонній зв\'язок\nAI-сповіщення\nПідписка Petcube Care з історією відео\nЧат із ліцензованим ветеринаром (Petcube Online Vet)', 'Власники котів і собак', 'mobile', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'petcube.com');
