INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Petcube Online Vet', NULL, 'month', 'чат із ліцензованим ветеринаром; ціну на сторінці не вказано' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Wag', NULL, 'https://www.wagwalking.com', NULL, NULL, 'Платформа для замовлення послуг для домашніх тварин: вигул, догляд удома, нічування, догляд у денному центрі та ветеринарний чат.', 'Wag з\'єднує власників тварин із місцевими виконавцями. Через застосунок можна замовити вигул, візити додому, нічування, догляд удома чи в денному центрі, тренування, ветеринарний чат, а також страхові й оздоровчі плани. Потрібно створити акаунт, додати тварину й подати заявку; можна обрати виконавця з профілів або довірити підбір платформі. Під час послуги застосунок показує GPS-маршрут, повідомлення та фото чи відео. За даними сторінки, вигули починаються від $18, а нічування коштує в середньому близько $51; сервіс працює у 5300 містах усіх штатів США. Є застосунки для iOS та Android і веб-версія.', 'Вигул, візити додому, нічування та денний догляд\nВетеринарний чат, страхові й оздоровчі плани\nGPS-відстеження, повідомлення, фото й відео під час послуги\nПрофілі виконавців та вибір власником\nЗастосунки для iOS, Android і веб-версія', 'Власники собак і котів, яким потрібен догляд або вигул', 'web,mobile', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'wagwalking.com');
