INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Pawp', NULL, 'https://www.pawp.com', NULL, NULL, 'Ветеринарна телемедицина 24/7: чат, відео та телефонні консультації з ліцензованими ветеринарами через застосунок.', 'Pawp — ветеринарна телемедична служба: у застосунку доступні повідомлення, відеодзвінки й телефонні консультації з ліцензованими ветеринарами, медсестрами та техніками цілодобово. Заявлено необмежену кількість візитів без оплати за окрему консультацію, індивідуальні плани догляду, персональні рекомендації та подальший супровід лікування. Застосунок є для iOS та Android; на сторінці згадано лише США.', 'Цілодобові консультації ветеринарів у чаті, відео й телефоном\nНеобмежена кількість візитів без оплати за окрему консультацію\nІндивідуальні плани догляду та рекомендації\nПодальший супровід лікування\nЗастосунки для iOS та Android', 'Власники домашніх тварин, яким потрібна швидка ветеринарна порада', 'mobile', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'pawp.com');
