INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE c.`slug` = 'my-home' AND s.`slug` = 'pet-grooming-vet';
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Fi', NULL, 'https://fitracking.com', NULL, NULL, 'Розумний нашийник для собак з GPS-відстеженням, моніторингом активності та AI-аналізом поведінки.', 'Fi — розумний нашийник, що поєднує GPS-відстеження у реальному часі та AI-моніторинг здоров\'я собаки. Він відстежує рух і сон, а AI аналізує, як собака їсть, п\'є, чухається, облизується та гавкає, щоб помічати незвичну поведінку. Є світлодіодний нічний ліхтарик, заряд тримається до 3 місяців, а функція «Search Party» сповіщає найближчих користувачів Fi, якщо собака в режимі втрати. Працює через застосунок для iOS та Android; членство платне, до пристрою входить місяць безкоштовно.', 'GPS-відстеження в реальному часі\nМоніторинг активності та сну\nAI-аналіз поведінки: їжа, питво, чухання, гавкіт\nФункція Search Party для пошуку загубленого собаки\nДо 3 місяців роботи від одного заряду', 'Власники собак', 'mobile', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fitracking.com');
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE c.`slug` = 'my-home';
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE c.`slug` = 'my-home' AND s.`slug` = 'pets';
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Navfarm', NULL, 'https://www.navfarm.com', NULL, NULL, 'Хмарна система керування птахофермою: від інкубації до реалізації, з обліком партій, кормів і здоров\'я.', 'Navfarm — хмарна система для птахівничих господарств «від інкубації до збору врожаю». Є модулі для батьківського стада, несучок, інкубаторію (овоскопія, облік інкубації, якість курчат), комерційних бройлерів, вирощування за договором, кормів (склад, запаси, витрати), переробки та торгівлі. Забезпечує моніторинг партій у реальному часі, контроль здоров\'я та біобезпеки, простежуваність, мобільний застосунок для працівників, кілька локацій і власні звіти. Є безкоштовний пробний період; ціни на сторінці не вказані.', 'Модулі: батьківське стадо, несучки, інкубаторій, бройлери\nМоніторинг партій у реальному часі\nОблік кормів: склад, запаси, витрати\nЗдоров\'я та біобезпека, простежуваність\nМобільний застосунок для працівників', 'Птахівничі господарства різного масштабу, зокрема з інкубаторіями', 'web,mobile', 'basic', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'navfarm.com');
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE c.`slug` = 'my-home';
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE c.`slug` = 'my-home' AND s.`slug` = 'poultry';
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'SmartBird', NULL, 'https://smartbirdapp.com', NULL, NULL, 'Хмарна програма для ведення птахоферми: облік яєць, кормів, здоров\'я птиці та фінансів у одному місці.', 'SmartBird зводить дані птахоферми в одну систему: щоденний облік яєць, вага птиці, динаміка росту й падіж, витрати кормів, записи про вакцинації, лікування й хвороби, облік доходів і витрат з експортом у QuickBooks, Xero, Sage, Zoho Books та Excel. Показує звіти й показники, зокрема коефіцієнт конверсії корму. Є командна робота з розмежуванням прав. Працює у вебі; застосунки для iOS та Android на сторінці позначені як «незабаром». Усі плани мають 7 днів безкоштовно.', 'Облік яєць, ваги птиці, росту й падежу\nВитрати кормів та вартість\nЗаписи про вакцинації, лікування й хвороби\nОблік доходів і витрат з експортом у бухгалтерські програми\nЗвіти та показники, зокрема коефіцієнт конверсії корму', 'Птахівничі ферми будь-якого масштабу', 'web', 'basic', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'smartbirdapp.com');
