INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Standard', 29.00, 'month', '5 користувачів, необмежена кількість зграй; 7 днів безкоштовно' FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Standard (річний)', 279.00, 'year', 'річна оплата плану Standard' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'PoultryPal', NULL, 'https://getpoultrypal.com', NULL, NULL, 'Застосунок для власників домашніх курей і малих ферм: облік птиці, яєць, інкубації, продажів і витрат.', 'PoultryPal допомагає вести облік птиці на домашньому подвір\'ї та малих фермах: профілі окремих птахів із породою й фото, щоденний облік яєць з автоматичними графіками, записи про інкубацію з відліком дат овоскопії та закладки, продажі, витрати й прибутковість, журнал подій та зведена панель. Працює на iOS та Android. Безкоштовна версія — одна зграя до 8 птахів, облік яєць, інкубація й журнал; платна Premium додає необмежені зграї, фінанси, книгу продажів і нагадування.', 'Профілі птахів із породою та фото\nОблік яєць з графіками\nЗаписи про інкубацію з нагадуваннями про овоскопію\nПродажі, витрати й прибутковість (Premium)\nЖурнал подій і зведена панель', 'Власники домашніх курей, господарі малих ферм', 'mobile', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'getpoultrypal.com');
