INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Free', 0.00, 'free', 'одна зграя до 8 птахів, облік яєць, інкубація й журнал' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Flockstar', NULL, 'https://www.flockstar.com', NULL, NULL, 'Застосунок для птахівників: облік зграй і окремих птахів, яєць, інкубації, родоводів і фінансів.', 'Flockstar централізує облік птахівничого господарства без таблиць і зошитів: зграї й профілі окремих птахів, облік несучості з аналізом тенденцій, інкубація з даними про заплідненість і виводимість, родоводи на три покоління, фінанси (витрати, продажі, прибуток, вартість яйця), журнал і завдання, візуалізація походження. Працює у вебі, на iOS та Android із синхронізацією. Обидва плани мають тиждень безкоштовно.', 'Облік зграй і окремих птахів\nОблік несучості з аналізом тенденцій\nІнкубація з даними про заплідненість і виводимість\nРодоводи на три покоління\nФінанси: витрати, продажі, прибуток, вартість яйця', 'Птахівники, заводчики й господарі малих ферм', 'web,mobile', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'flockstar.com');
