INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'FlockFriend', NULL, 'https://apps.apple.com/us/app/flockfriend-chicken-tracker/id6745474579', NULL, NULL, 'Застосунок для власників курей: облік яєць одним дотиком, профілі несучок і нагадування.', 'FlockFriend створений власниками домашніх курей для таких самих господарів. Яйця записуються одним дотиком із миттєвою статистикою, у профілі кожної несучки зберігаються фото, порода, дата вилуплення та записи про здоров\'я. Графіки показують несучість за днями, тижнями чи місяцями, є нагадування про збір яєць, чистку курника та перевірку здоров\'я, а дані синхронізуються через iCloud. Завантаження безкоштовне; додаткові можливості — за підпискою Pro.', 'Облік яєць одним дотиком\nПрофілі несучок із фото, породою й записами про здоров\'я\nГрафіки несучості за днями, тижнями й місяцями\nНагадування про збір яєць, чистку курника й перевірку здоров\'я\nСинхронізація через iCloud', 'Власники домашніх курей і невеликих господарств', 'mobile', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'apps.apple.com/us/app/flockfriend-chicken-tracker/id6745474579');
