INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Fishial', NULL, 'https://www.fishial.ai', NULL, NULL, 'Безкоштовна AI-платформа для визначення видів риб за фото, яку підтримує Wye Foundation.', 'Fishial.AI поєднує штучний інтелект і науку про риб, щоб визначати види риб у всьому світі для освіти й охорони природи. Модель ШІ з відкритим кодом навчена на розмічених зображеннях; є вебпортал для внесків громадянської науки, API для розробників та безкоштовний мобільний застосунок. Наразі система розпізнає 640 видів риб, зібрано понад 2,6 млн зображень, з них 175 тисяч відібрано для навчання. Користуються рибалки, науковці, освітяни, діти та фахівці з рибних ресурсів.', 'Визначення виду риби за фото\nМодель ШІ з відкритим кодом\nВебпортал для внесків громадянської науки\nAPI для розробників\nБезкоштовний мобільний застосунок', 'Рибалки, науковці, освітяни та любителі природи', 'web,mobile', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'fishial.ai');
