INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Seneye', NULL, 'https://www.seneye.com', NULL, NULL, 'Розумні пристрої для моніторингу якості води в акваріумі чи ставку із сповіщеннями на пошту, SMS або індикатором.', 'Seneye випускає пристрої, які автоматично стежать за станом води в акваріумі чи ставку та попереджають електронною поштою, SMS або світловим індикатором. Вимірює pH, вільний аміак, температуру та освітленість (параметри PAR і LUX). Є рішення для аматорських акваріумів, екологічного моніторингу річок і озер та промислової аквакультури; компанія має сертифікацію ISO 9001:2015. На сторінці згадано мобільну платформу й демо-панель для аматорського пристрою.', 'Вимірювання pH, вільного аміаку, температури та освітленості\nСповіщення на пошту, SMS або світловим індикатором\nРішення для акваріумів, ставків, річок і аквакультури\nДемо-панель для аматорського пристрою', 'Акваріумісти, власники ставків та господарства аквакультури', 'mobile', 'basic', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'seneye.com');
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE c.`slug` = 'my-home';
