INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Neptune Systems Apex', NULL, 'https://www.neptunesystems.com', NULL, NULL, 'Контролер і система моніторингу морського акваріума з автоматизацією, сповіщеннями та застосунком Apex Fusion.', 'Neptune Systems Apex — контролер акваріума, що цілодобово стежить за морським акваріумом. Відстежує магній, кальцій, лужність, температуру, pH, витоки води та відключення живлення, надсилає сповіщення на мобільний, пошту й звуком, коли показники виходять за межі. Автоматично реагує, наприклад вимикає несправний нагрівач чи запускає дозування буфера. Є різні датчики, автоматичний тест Trident, що прибирає ручні вимірювання, і модуль MXM для підключення обладнання інших виробників. Керувати можна віддалено через застосунок Apex Fusion.', 'Моніторинг магнію, кальцію, лужності, температури, pH\nСповіщення на мобільний, пошту й звуком\nАвтоматичні реакції на відхилення показників\nАвтоматичний тест Trident\nВіддалене керування через Apex Fusion', 'Власники морських акваріумів та рифів', 'web,mobile', 'basic', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'neptunesystems.com');
