INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Aquarimate', NULL, 'https://www.aquarimate.com', NULL, NULL, 'Застосунок для догляду за акваріумом: облік параметрів води, нагадування про обслуговування та база видів риб.', 'Aquarimate допомагає вести акваріум: журнал параметрів води з історією та графіками, нагадування про підміни води, годування, дозування й обслуговування обладнання, облік мешканців із фото та станом здоров\'я, аналітика зв\'язку дій із зміною параметрів, облік витрат та галерея фото. Є база Aquaribase з тисячами видів морських і прісноводних мешканців. Працює на iOS, Android, Mac і Windows; калькулятори дозування — лише в iOS. Версія Aquarimate Live із хмарою коштує $9.99 на рік, є гарантія повернення коштів.', 'Журнал параметрів води з графіками\nНагадування про підміни води, годування й обслуговування\nОблік мешканців із фото та станом здоров\'я\nБаза Aquaribase із тисячами видів\nВерсії для iOS, Android, Mac і Windows', 'Власники прісноводних і морських акваріумів', 'mobile,desktop', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'aquarimate.com');
