INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Aquarium Tracker', NULL, 'https://getaquariumtracker.app', NULL, NULL, 'Безкоштовний застосунок для догляду за акваріумом: параметри води, завдання з нагадуваннями, облік мешканців і калькулятори.', 'Aquarium Tracker збирає в одному місці результати тестів води, регулярні завдання, облік риб і рослин та історію акваріума. Параметри записуються з графіками й цільовими діапазонами, завдання мають нагадування, а єдина стрічка історії об\'єднує параметри, мешканців, обладнання й нотатки. Є бібліотека видів із вимогами до догляду й сумісністю та калькулятори об\'єму, наповнення, підмін води, CO₂, дозування й ґрунту. У платній версії AquaMind — помічник на основі AI, який аналізує дані акваріума. Застосунок безкоштовний для iOS та Android.', 'Журнал параметрів води з графіками\nЗавдання й нагадування з історією виконання\nОблік мешканців і рослин по акваріумах\nБібліотека видів із сумісністю\nAI-помічник AquaMind (Pro)', 'Акваріумісти', 'mobile', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'getaquariumtracker.app');
