INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Aquarium Manager: Tank Log', NULL, 'https://apps.apple.com/us/app/aquarium-manager-tank-log/id614505498', NULL, NULL, 'Застосунок для ведення прісноводних і морських акваріумів: мешканці, обладнання, параметри води та енциклопедія.', 'Aquarium Manager: Tank Log веде облік необмеженої кількості акваріумів: риб, безхребетних і рослин, обладнання (фільтри, освітлення, нагрівачі), параметрів води (pH, температура, нітрити, нітрати, GH, KH) із графіками та журналу обслуговування — підміни води, чистки фільтра, обрізання рослин. Записує події — додавання мешканців, хвороби, розмноження — з нагадуваннями, має вбудовану енциклопедію риб і рослин та нотатки з фото. Базова версія безкоштовна з рекламою; є платні розширення.', 'Облік риб, безхребетних, рослин і обладнання\nЖурнал параметрів води з графіками\nЖурнал обслуговування та події з нагадуваннями\nВбудована енциклопедія риб і рослин\nНотатки та фото', 'Власники прісноводних і морських акваріумів', 'mobile', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'apps.apple.com/us/app/aquarium-manager-tank-log/id614505498');
