INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `price`, `period`, `description`) SELECT @pid, 'Підписка (рік)', 12.99, 'year', 'оплата в застосунку (App Store)' FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Beentry', NULL, 'https://www.beentry.com', NULL, NULL, 'Застосунок для пасічників: голосові записи оглядів вуликів з AI, облік пасік і сімей та AI-порадник.', 'Beentry — платформа керування пасікою від чеської компанії PunkHive. Голосова диктовка автоматично створює структуровані записи огляду вулика: стан сім\'ї, підживлення, обробки, нотатки. Дає змогу вести облік здоров\'я сімей і історії маток на необмеженій кількості пасік, відстежувати збір меду по сім\'ях та отримувати сповіщення про спалахи хвороб поруч. AI-порадник підказує з урахуванням даних та сезону. Є вебпанель зі статистикою та експортом, застосунки для iOS та Android. Доступна англійською, чеською, німецькою, польською, словацькою та французькою; 30 днів безкоштовно.', 'Голосові AI-записи оглядів вуликів\nОблік сімей, маток і збору меду на необмеженій кількості пасік\nСповіщення про спалахи хвороб поруч\nAI-порадник з урахуванням даних і сезону\nВебпанель зі статистикою та експортом', 'Пасічники', 'web,mobile', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'beentry.com');
