INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'ApiManager', NULL, 'https://apimanager.net', NULL, NULL, 'Застосунок і вебпанель для пасічників: огляди, завдання, збір меду, обробки, фінанси та статистика.', 'ApiManager допомагає вести пасіку: записувати огляди зі своїми шаблонами, планувати завдання й нагадування, обліковувати збір меду, підживлення, обробки та фінанси, а також дивитися звіти й графіки. Є облік стану маток і їх зміни, історія сімей, порівняння вуликів, облік кормової бази, моніторинг кліща варроа та погодні дані. Працює на iOS, Android, Mac, Windows і в браузері із синхронізацією через хмару, експорт в Excel та CSV; доступний понад 34 мовами.', 'Огляди зі своїми шаблонами й завдання з нагадуваннями\nОблік збору меду, підживлення, обробок і фінансів\nІсторія сімей і порівняння вуликів\nСтан маток і моніторинг кліща варроа\nСинхронізація між iOS, Android, Mac, Windows і вебом', 'Пасічники різного масштабу', 'web,mobile,desktop', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'apimanager.net');
