INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'BeeScanning', NULL, 'https://www.beescanning.com', NULL, NULL, 'Застосунок для пасічників, що поєднує пошук кліща варроа з веденням вуликів і сімей.', 'BeeScanning — мобільний застосунок для пасічників, який поєднує виявлення кліща варроа з інструментами керування пасікою. Веде облік стану вуликів, журнал робіт і планування завдань, керування бджолиними сім\'ями. Створений шведською компанією «бджолярами для бджолярів»; доступний для iOS та Android. Тарифи існують, але ціни на головній сторінці не вказані.', 'Виявлення та облік кліща варроа\nСтан і здоров\'я вуликів\nЖурнал робіт і планування завдань\nКерування бджолиними сім\'ями', 'Пасічники', 'mobile', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'beescanning.com');
