INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Hive Pal', NULL, 'https://hivepal.app', NULL, NULL, 'Безкоштовна платформа для пасічників з відкритим кодом: пасіки, огляди, матки, збір меду та AI-голосові огляди.', 'Hive Pal — безкоштовна платформа з відкритим кодом (ліцензія MIT) для керування пасікою: облік кількох пасік із погодою, огляди з гнучкими чек-листами, фото та оцінкою здоров\'я, відстеження маток і їх племінних записів, облік збору меду й продуктивності. Виділяється AI-голосовими оглядами: голосові нотатки біля вулика транскрибуються й перетворюються на чернетки оглядів моделями з відкритим кодом (Faster-Whisper, Ollama). Можна розгорнути на власному сервері (Docker, Raspberry Pi) або користуватися хмарною версією, без абонплати.', 'Облік кількох пасік із погодою\nОгляди з чек-листами, фото й оцінкою здоров\'я\nВідстеження маток і племінних записів\nОблік збору меду\nAI-голосові огляди на моделях з відкритим кодом', 'Пасічники, зокрема ті, хто хоче розмістити систему в себе', NULL, 'basic', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hivepal.app');
