INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Paprika Recipe Manager', NULL, 'https://www.paprikaapp.com', NULL, NULL, 'Застосунок для зберігання рецептів, планування меню й списків покупок із синхронізацією між пристроями.', 'Paprika допомагає впорядкувати рецепти, скласти план харчування та списки покупок. Вбудований браузер зберігає рецепти з інтернету одним дотиком, дані синхронізуються між усіма пристроями. Розумні списки покупок сортують інгредієнти за відділами й об\'єднують однакові, план меню складається на тиждень чи місяць зі збереженими шаблонами. В інтерактивному рецепті можна масштабувати кількість інгредієнтів, відстежувати кроки, автоматично знаходити таймери та закріплювати активні рецепти; є облік запасів. Працює на iOS, Mac, Android та Windows; кожна версія продається окремо.', 'Збереження рецептів з інтернету одним дотиком\nПлани меню на тиждень чи місяць із шаблонами\nРозумні списки покупок за відділами\nМасштабування інгредієнтів і автоматичні таймери\nОблік запасів продуктів', 'Домашні кухарі, які хочуть впорядкувати рецепти та планувати меню', 'mobile,desktop', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'paprikaapp.com');
