INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `full_description`, `main_features`, `target_audience`, `platform`, `skill_level`, `status`, `partnership_status`, `created_at`) SELECT 'Cookpad', NULL, 'https://cookpad.com/us', NULL, NULL, 'Спільнота домашніх кухарів: створюйте, зберігайте й діліться рецептами та фото приготованих страв.', 'Cookpad — спільнота домашніх кухарів з усього світу, де можна створювати, зберігати й публікувати рецепти та ділитися досвідом. Є «cooksnaps» — фото приготованих за рецептом страв, особиста бібліотека рецептів і преміум-доступ до добірок найпопулярніших рецептів. Працює у вебі та має застосунки для iOS і Android; на сторінці показано понад 25 регіональних спільнот.', 'Створення та публікація власних рецептів\nCooksnaps — фото приготованих страв\nОсобиста бібліотека рецептів\nПреміум-добірки популярних рецептів\nВеб, iOS та Android', 'Домашні кухарі та любителі нових рецептів', 'web,mobile', 'none', 'published', 'found', '2026-09-21 00:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'cookpad.com/us');
